INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind digitale Plattformen immer Cloud-basiert?', 2, '[{"text": "Nein", "correct": true, "because": "Können auch lokal laufen"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend Cloud"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgen digitale Plattformen?', 3, '[{"text": "Interaktion ermöglichen", "correct": true, "because": "Nutzer verbinden"}, {"text": "Hardware verkaufen", "correct": false, "because": "Fokus auf Dienst"}, {"text": "Kosten erhöhen", "correct": false, "because": "Effizienz im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale haben digitale Plattformen?', 5, '[{"text": "Skalierbarkeit", "correct": true, "because": "Wachstum möglich"}, {"text": "Netzwerkeffekte", "correct": true, "because": "Mehr Nutzer, mehr Wert"}, {"text": "Hoher Stromverbrauch", "correct": false, "because": "Nicht primär"}, {"text": "Physische Präsenz", "correct": false, "because": "Digital fokussiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Digitale Plattformen verbinden Nutzer. b) Sie sind nur für Unternehmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Privatnutzer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Nutzung digitaler Plattformen?', 4, '[{"text": "Internetverbindung", "correct": false, "because": "Grundvoraussetzung"}, {"text": "Benutzerfreundlichkeit", "correct": false, "because": "Wichtig für Erfolg"}, {"text": "Bürodekor", "correct": true, "because": "Kein digitaler Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob digitale Plattformen nur Handel betreiben?', 2, '[{"text": "Nein", "correct": true, "because": "Auch soziale Dienste"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel ist eine digitale Plattform?', 3, '[{"text": "Amazon", "correct": true, "because": "Marktplatz für Nutzer"}, {"text": "Microsoft Word", "correct": false, "because": "Software, kein Netzwerk"}, {"text": "USB-Stick", "correct": false, "because": "Hardware"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten digitale Plattformen?', 5, '[{"text": "Effiziente Vernetzung", "correct": true, "because": "Nutzer verbinden"}, {"text": "Schnelle Skalierung", "correct": true, "because": "Wachstum leicht"}, {"text": "Hohe Anfangskosten", "correct": false, "because": "Oft kosteneffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Digitale Plattformen leben von Nutzern. b) Sie brauchen lokale Server. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Server oft in Cloud"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine digitale Plattform?', 4, '[{"text": "Technische Infrastruktur", "correct": false, "because": "Grundlage"}, {"text": "Nutzerbasis", "correct": false, "because": "Treibt Wert"}, {"text": "Physische Filialen", "correct": true, "because": "Digital ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind digitale Plattformen immer kostenlos?', 2, '[{"text": "Nein", "correct": true, "because": "Viele haben Gebühren"}, {"text": "Ja", "correct": false, "because": "Nicht immer kostenfrei"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien unterstützen digitale Plattformen?', 4, '[{"text": "Cloud", "correct": true, "because": "Skalierbare Basis"}, {"text": "APIs", "correct": true, "because": "Integration ermöglichen"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Automatisierung zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass digitale Plattformen nur für E-Commerce sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch soziale Netzwerke"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei digitalen Plattformen?', 3, '[{"text": "Nutzererfahrung", "correct": true, "because": "Bindet Nutzer"}, {"text": "Hohe Hardwarekosten", "correct": false, "because": "Effizienz zählt"}, {"text": "Langsame Updates", "correct": false, "because": "Schnelligkeit wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Digitale Plattformen nutzen Netzwerkeffekte. b) Sie sind lokal begrenzt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Global möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Plattformen gibt es?', 5, '[{"text": "Marktplätze", "correct": true, "because": "Handel verbinden"}, {"text": "Soziale Netzwerke", "correct": true, "because": "Interaktion fördern"}, {"text": "Physische Läden", "correct": false, "because": "Nicht digital"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei digitalen Plattformen unwichtig?', 3, '[{"text": "Zugänglichkeit", "correct": false, "because": "Erfolgskriterium"}, {"text": "Skalierbarkeit", "correct": false, "because": "Wachstum ermöglichen"}, {"text": "Papierkataloge", "correct": true, "because": "Analog irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Brauchen digitale Plattformen immer eine App?', 3, '[{"text": "Nein", "correct": true, "because": "Auch Web möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend App"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob digitale Plattformen nur für Kunden sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch B2B möglich"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature macht digitale Plattformen wertvoll?', 4, '[{"text": "Netzwerkeffekte", "correct": true, "because": "Mehr Nutzer, mehr Nutzen"}, {"text": "Hohe Anfangskosten", "correct": false, "because": "Nicht entscheidend"}, {"text": "Lokale Server", "correct": false, "because": "Cloud oft genutzt"}]');
